// Auto-generated bundled migrations to avoid ENOENT errors in serverless environments like Vercel
export const MIGRATIONS_DATA: Record<string, string> = {
  "001-identity.sql": "CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS demo_tenants (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS app_users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('member','president','treasurer','cooperative','ngo')));\nCREATE TABLE IF NOT EXISTS memberships (tenant_id text NOT NULL REFERENCES demo_tenants(id), user_id text NOT NULL REFERENCES app_users(id), org_id text NOT NULL, role text NOT NULL, PRIMARY KEY(tenant_id,user_id,org_id));\nCREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, tenant_id text NOT NULL REFERENCES demo_tenants(id), user_id text NOT NULL REFERENCES app_users(id), expires_at timestamptz NOT NULL);\nCREATE TABLE IF NOT EXISTS goals (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES demo_tenants(id), user_id text NOT NULL REFERENCES app_users(id), name text NOT NULL, target bigint NOT NULL CHECK(target>0 AND target<=1000000000000), saved bigint NOT NULL CHECK(saved>=0 AND saved<=1000000000000), deadline date NOT NULL);\nCREATE TABLE IF NOT EXISTS interventions (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES demo_tenants(id), org_id text NOT NULL, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES demo_tenants(id), user_id text NOT NULL REFERENCES app_users(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());\nCREATE INDEX IF NOT EXISTS goals_owner ON goals(tenant_id,user_id);\nCREATE INDEX IF NOT EXISTS notification_owner ON notifications(tenant_id,user_id);\n",
  "002-finance.sql": "CREATE TABLE IF NOT EXISTS finance_orgs (\n tenant_id text NOT NULL REFERENCES demo_tenants(id), org_id text NOT NULL,\n name text NOT NULL, kind text NOT NULL CHECK(kind IN ('group','fund','cooperative')),\n district text NOT NULL DEFAULT 'Gasabo', member_count integer NOT NULL DEFAULT 0,\n reserve_bps integer NOT NULL DEFAULT 2000 CHECK(reserve_bps BETWEEN 0 AND 10000),\n loan_limit_bps integer NOT NULL DEFAULT 5000 CHECK(loan_limit_bps BETWEEN 0 AND 10000),\n PRIMARY KEY(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_entries (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL,\n description text NOT NULL, reference text NOT NULL, reversal_of text,\n posting_txid bigint NOT NULL DEFAULT txid_current(),\n created_at timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id),\n UNIQUE(tenant_id,org_id,reference), UNIQUE(tenant_id,org_id,reversal_of)\n);\nCREATE TABLE IF NOT EXISTS finance_lines (\n id text PRIMARY KEY, entry_id text NOT NULL REFERENCES finance_entries(id),\n tenant_id text NOT NULL, org_id text NOT NULL, account text NOT NULL, user_id text,\n debit bigint NOT NULL DEFAULT 0 CHECK(debit BETWEEN 0 AND 9007199254740991),\n credit bigint NOT NULL DEFAULT 0 CHECK(credit BETWEEN 0 AND 9007199254740991),\n CHECK((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0)),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE INDEX IF NOT EXISTS finance_lines_scope ON finance_lines(tenant_id,org_id,account,user_id);\nCREATE OR REPLACE FUNCTION finance_immutable() RETURNS trigger LANGUAGE plpgsql AS $$\n BEGIN RAISE EXCEPTION 'Posted journals are immutable; create a reversal'; END;\n$$;\nCREATE TRIGGER finance_entries_immutable BEFORE UPDATE OR DELETE ON finance_entries FOR EACH ROW EXECUTE FUNCTION finance_immutable();\nCREATE TRIGGER finance_lines_immutable BEFORE UPDATE OR DELETE ON finance_lines FOR EACH ROW EXECUTE FUNCTION finance_immutable();\nCREATE OR REPLACE FUNCTION finance_validate_line_scope() RETURNS trigger LANGUAGE plpgsql AS $$\n BEGIN\n  IF NOT EXISTS (SELECT 1 FROM finance_entries WHERE id=NEW.entry_id AND tenant_id=NEW.tenant_id AND org_id=NEW.org_id AND posting_txid=txid_current()) THEN\n   RAISE EXCEPTION 'Journal lines must be posted with their entry in the same transaction, tenant and organization';\n  END IF;\n  RETURN NEW;\n END;\n$$;\nCREATE TRIGGER finance_lines_scope BEFORE INSERT ON finance_lines FOR EACH ROW EXECUTE FUNCTION finance_validate_line_scope();\nCREATE OR REPLACE FUNCTION finance_validate_balance() RETURNS trigger LANGUAGE plpgsql AS $$\n DECLARE scoped_entry text; debits numeric; credits numeric; line_count integer;\n BEGIN\n  IF TG_TABLE_NAME='finance_entries' THEN scoped_entry=NEW.id; ELSE scoped_entry=NEW.entry_id; END IF;\n  SELECT COALESCE(SUM(debit),0),COALESCE(SUM(credit),0),COUNT(*) INTO debits,credits,line_count FROM finance_lines WHERE entry_id=scoped_entry;\n  IF line_count<2 OR debits<>credits OR debits<=0 THEN RAISE EXCEPTION 'Posted journal must have balanced debit and credit lines'; END IF;\n  RETURN NEW;\n END;\n$$;\nCREATE CONSTRAINT TRIGGER finance_entry_balance AFTER INSERT ON finance_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_validate_balance();\nCREATE CONSTRAINT TRIGGER finance_line_balance AFTER INSERT ON finance_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_validate_balance();\nCREATE TABLE IF NOT EXISTS finance_loans (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, user_id text NOT NULL,\n amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991), months integer NOT NULL CHECK(months BETWEEN 1 AND 24),\n status text NOT NULL CHECK(status IN ('requested','declined','disbursing','active','repaid','failed','reversed')),\n approved_by text, created_at timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_campaigns (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, title text NOT NULL,\n category text NOT NULL, description text NOT NULL,\n target bigint NOT NULL CHECK(target > 0 AND target <= 9007199254740991), status text NOT NULL DEFAULT 'active',\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_expenses (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, campaign_id text NOT NULL REFERENCES finance_campaigns(id),\n title text NOT NULL, amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991),\n requested_by text NOT NULL, approved_by text, status text NOT NULL DEFAULT 'requested',\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_payments (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, user_id text NOT NULL,\n kind text NOT NULL CHECK(kind IN ('contribution','loan','repayment','donation','expense')),\n amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991),\n status text NOT NULL CHECK(status IN ('success','failed','pending','unknown')),\n reference text NOT NULL, loan_id text, campaign_id text, expense_id text,\n journal_id text REFERENCES finance_entries(id), synthetic boolean NOT NULL DEFAULT true CHECK(synthetic),\n created_at timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id),\n UNIQUE(tenant_id,org_id,reference)\n);\nCREATE INDEX IF NOT EXISTS finance_payments_scope ON finance_payments(tenant_id,org_id,status,kind);\nCREATE TABLE IF NOT EXISTS finance_proposals (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, title text NOT NULL,\n amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991),\n status text NOT NULL DEFAULT 'proposed', created_by text NOT NULL,\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_votes (\n tenant_id text NOT NULL, org_id text NOT NULL, proposal_id text NOT NULL REFERENCES finance_proposals(id), user_id text NOT NULL,\n PRIMARY KEY(tenant_id,org_id,proposal_id,user_id),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE IF NOT EXISTS finance_audit (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL,\n sequence bigint NOT NULL CHECK(sequence>0), action text NOT NULL, actor_id text NOT NULL, actor_role text NOT NULL,\n details text NOT NULL, created_at timestamptz NOT NULL,\n prev_hash text NOT NULL, hash text NOT NULL CHECK(length(hash)=64),\n UNIQUE(tenant_id,org_id,sequence),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TRIGGER finance_audit_immutable BEFORE UPDATE OR DELETE ON finance_audit FOR EACH ROW EXECUTE FUNCTION finance_immutable();\n",
  "003-firebase-accounts.sql": "CREATE TABLE IF NOT EXISTS account_profiles (\n user_id text PRIMARY KEY REFERENCES app_users(id),\n tenant_id text NOT NULL REFERENCES demo_tenants(id),\n status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),\n is_test_account boolean NOT NULL DEFAULT false,\n created_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE TABLE IF NOT EXISTS firebase_sessions (\n token_hash text PRIMARY KEY,\n user_id text NOT NULL REFERENCES account_profiles(user_id),\n created_at timestamptz NOT NULL DEFAULT now(),\n expires_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS firebase_sessions_user ON firebase_sessions(user_id);\n",
  "004-dual-savings-groups.sql": "ALTER TABLE finance_orgs ADD COLUMN savings_model text CHECK(savings_model IN ('ACCUMULATING','ROTATING'));\nUPDATE finance_orgs SET savings_model='ACCUMULATING' WHERE kind='group' AND savings_model IS NULL;\nALTER TABLE finance_orgs ADD CONSTRAINT finance_org_group_model CHECK((kind='group' AND savings_model IS NOT NULL) OR (kind<>'group' AND savings_model IS NULL));\n\nCREATE TABLE savings_group_policies (\n tenant_id text NOT NULL, org_id text NOT NULL,\n description text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '',\n expected_members integer NOT NULL DEFAULT 5 CHECK(expected_members BETWEEN 2 AND 500),\n contribution_amount bigint NOT NULL DEFAULT 10000 CHECK(contribution_amount BETWEEN 1 AND 9007199254740991),\n contribution_frequency text NOT NULL DEFAULT 'monthly' CHECK(contribution_frequency IN ('daily','weekly','monthly')),\n contribution_type text NOT NULL DEFAULT 'fixed' CHECK(contribution_type IN ('fixed','variable')),\n due_day integer NOT NULL DEFAULT 1 CHECK(due_day BETWEEN 1 AND 31),\n rotation_order jsonb NOT NULL DEFAULT '[]'::jsonb,\n partial_policy text NOT NULL DEFAULT 'allow' CHECK(partial_policy IN ('allow','full_only')),\n missed_policy text NOT NULL DEFAULT 'flag' CHECK(missed_policy IN ('flag','delay_round')),\n late_penalty bigint NOT NULL DEFAULT 0 CHECK(late_penalty BETWEEN 0 AND 9007199254740991),\n cycle_start date, cycle_end date, share_out_date date,\n minimum_reserve_bps integer NOT NULL DEFAULT 2000 CHECK(minimum_reserve_bps BETWEEN 0 AND 10000),\n emergency_lending boolean NOT NULL DEFAULT true,\n loan_limit_bps integer NOT NULL DEFAULT 5000 CHECK(loan_limit_bps BETWEEN 0 AND 10000),\n distribution_rule text NOT NULL DEFAULT 'proportional' CHECK(distribution_rule IN ('proportional','equal')),\n accepted_by text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(),\n PRIMARY KEY(tenant_id,org_id), FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE savings_cycles (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL,\n start_date date NOT NULL, end_date date NOT NULL, status text NOT NULL DEFAULT 'collecting' CHECK(status IN ('collecting','frozen','settling','closed')),\n closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id), CHECK(end_date>start_date)\n);\nCREATE UNIQUE INDEX savings_one_open_cycle ON savings_cycles(tenant_id,org_id) WHERE status<>'closed';\nCREATE TABLE savings_rotation_rounds (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, cycle_id text NOT NULL REFERENCES savings_cycles(id),\n round_number integer NOT NULL CHECK(round_number>0), recipient_user_id text NOT NULL,\n due_date date NOT NULL, expected_pool bigint NOT NULL CHECK(expected_pool BETWEEN 0 AND 9007199254740991),\n status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','collecting','ready','approved','pending','paid','delayed','failed','unknown','cancelled')),\n actual_paid bigint NOT NULL DEFAULT 0 CHECK(actual_paid BETWEEN 0 AND 9007199254740991), payout_reference text,\n UNIQUE(tenant_id,org_id,cycle_id,round_number), UNIQUE(tenant_id,org_id,cycle_id,recipient_user_id),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nCREATE TABLE savings_obligations (\n id text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, cycle_id text NOT NULL REFERENCES savings_cycles(id),\n round_id text REFERENCES savings_rotation_rounds(id), user_id text NOT NULL,\n amount_due bigint NOT NULL CHECK(amount_due BETWEEN 1 AND 9007199254740991), amount_confirmed bigint NOT NULL DEFAULT 0 CHECK(amount_confirmed BETWEEN 0 AND 9007199254740991),\n due_date date NOT NULL, status text NOT NULL DEFAULT 'due' CHECK(status IN ('due','partial','paid','missed','waived')),\n UNIQUE(tenant_id,org_id,cycle_id,round_id,user_id), FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id), CHECK(amount_confirmed<=amount_due)\n);\nCREATE TABLE savings_group_invites (\n invite_code text PRIMARY KEY, tenant_id text NOT NULL, org_id text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(tenant_id,org_id) REFERENCES finance_orgs(tenant_id,org_id)\n);\nINSERT INTO savings_group_policies(tenant_id,org_id,expected_members,cycle_start,cycle_end,accepted_by)\n SELECT tenant_id,org_id,GREATEST(member_count,2),CURRENT_DATE,(CURRENT_DATE+interval '1 year')::date,'system-migration'\n FROM finance_orgs WHERE kind='group' ON CONFLICT(tenant_id,org_id) DO NOTHING;\nINSERT INTO savings_cycles(id,tenant_id,org_id,start_date,end_date)\n SELECT 'cycle-migrated-'||tenant_id||'-'||org_id,tenant_id,org_id,cycle_start,cycle_end\n FROM savings_group_policies p WHERE NOT EXISTS(SELECT 1 FROM savings_cycles c WHERE c.tenant_id=p.tenant_id AND c.org_id=p.org_id AND c.status<>'closed');\nCREATE INDEX savings_group_invites_scope ON savings_group_invites(tenant_id,org_id);\nALTER TABLE finance_payments ADD COLUMN obligation_id text REFERENCES savings_obligations(id);\nALTER TABLE finance_payments ADD COLUMN rotation_round_id text REFERENCES savings_rotation_rounds(id);\nALTER TABLE finance_payments ADD COLUMN cycle_id text REFERENCES savings_cycles(id);\nCREATE UNIQUE INDEX savings_unique_round_payout ON finance_payments(tenant_id,org_id,rotation_round_id) WHERE kind='group-payout' AND rotation_round_id IS NOT NULL AND status IN ('pending','unknown','success');\nALTER TABLE finance_payments DROP CONSTRAINT IF EXISTS finance_payments_kind_check;\nALTER TABLE finance_payments ADD CONSTRAINT finance_payments_kind_check CHECK(kind IN ('contribution','loan','repayment','donation','expense','group-payout','share-out'));\nCREATE UNIQUE INDEX savings_unique_shareout ON finance_payments(tenant_id,org_id,cycle_id,user_id) WHERE kind='share-out' AND cycle_id IS NOT NULL AND status IN ('pending','unknown','success');\n\nCREATE FUNCTION prevent_savings_model_change() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF OLD.kind='group' AND NEW.savings_model IS DISTINCT FROM OLD.savings_model THEN RAISE EXCEPTION 'A savings group model cannot be changed after creation'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER finance_org_savings_model_immutable BEFORE UPDATE OF savings_model ON finance_orgs FOR EACH ROW EXECUTE FUNCTION prevent_savings_model_change();\n",
  "005-workspace-onboarding.sql": "CREATE TABLE IF NOT EXISTS workspace_onboarding_requests (\n id text PRIMARY KEY,\n tenant_id text NOT NULL REFERENCES demo_tenants(id),\n user_id text NOT NULL REFERENCES account_profiles(user_id),\n purpose text NOT NULL CHECK (purpose IN ('fundraising','cooperative','impact')),\n organization_name text NOT NULL,\n district text NOT NULL,\n description text NOT NULL,\n status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted')),\n created_at timestamptz NOT NULL DEFAULT now(),\n UNIQUE (tenant_id,user_id,purpose)\n);\nCREATE INDEX IF NOT EXISTS workspace_onboarding_owner ON workspace_onboarding_requests(tenant_id,user_id);\n",
  "006-google-sheets-bindings.sql": "CREATE TABLE IF NOT EXISTS organization_sheet_bindings (\n tenant_id text NOT NULL,\n org_id text NOT NULL,\n spreadsheet_id text NOT NULL UNIQUE CHECK (spreadsheet_id ~ '^[A-Za-z0-9_-]{10,200}$'),\n created_at timestamptz NOT NULL DEFAULT now(),\n PRIMARY KEY (tenant_id, org_id),\n FOREIGN KEY (tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n",
  "007-organization-sheet-outbox.sql": "-- Durable organization-only delivery intent. This migration never exports data.\n-- Worker contract: serialize delivery using a SEPARATE destination lock, never\n-- this coalescing row across network I/O. Read a revision, write its snapshot,\n-- then briefly acknowledge that revision without overwriting a newer desired\n-- revision. New changes must remain pending if desired exceeds the sent revision.\nCREATE TABLE organization_sheet_outbox (\n tenant_id text NOT NULL,\n org_id text NOT NULL,\n desired_revision bigint NOT NULL DEFAULT 1 CHECK (desired_revision > 0),\n delivered_revision bigint NOT NULL DEFAULT 0 CHECK (delivered_revision >= 0 AND delivered_revision <= desired_revision),\n status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','synced','blocked')),\n updated_at timestamptz NOT NULL DEFAULT now(),\n PRIMARY KEY (tenant_id, org_id),\n FOREIGN KEY (tenant_id, org_id) REFERENCES organization_sheet_bindings(tenant_id, org_id) ON DELETE CASCADE,\n CHECK (status <> 'synced' OR delivered_revision = desired_revision)\n);\n\nCREATE FUNCTION enqueue_organization_sheet(p_tenant text, p_org text) RETURNS void\nLANGUAGE plpgsql AS $$\nBEGIN\n -- Hold the binding against deletion until this transaction finishes. Unbound\n -- scopes create no queue row. The conflict update locks and increments the\n -- current row atomically, so concurrent committed changes cannot be lost.\n PERFORM 1 FROM organization_sheet_bindings\n  WHERE tenant_id=p_tenant AND org_id=p_org FOR SHARE;\n IF NOT FOUND THEN RETURN; END IF;\n INSERT INTO organization_sheet_outbox(tenant_id,org_id)\n VALUES(p_tenant,p_org)\n ON CONFLICT(tenant_id,org_id) DO UPDATE\n SET desired_revision=organization_sheet_outbox.desired_revision+1,\n     status='pending', updated_at=now();\nEND;\n$$;\n\nCREATE FUNCTION queue_organization_sheet_change() RETURNS trigger\nLANGUAGE plpgsql AS $$\nBEGIN\n IF TG_OP='DELETE' THEN\n  PERFORM enqueue_organization_sheet(OLD.tenant_id,OLD.org_id);\n ELSIF TG_OP='INSERT' THEN\n  PERFORM enqueue_organization_sheet(NEW.tenant_id,NEW.org_id);\n ELSE\n  -- Queue both destinations if a mutable record changes scope; ordinary\n  -- updates enqueue only once. No record content is retained in the queue.\n  PERFORM enqueue_organization_sheet(NEW.tenant_id,NEW.org_id);\n  IF (OLD.tenant_id,OLD.org_id) IS DISTINCT FROM (NEW.tenant_id,NEW.org_id) THEN\n   PERFORM enqueue_organization_sheet(OLD.tenant_id,OLD.org_id);\n  END IF;\n END IF;\n RETURN NULL;\nEND;\n$$;\n\nCREATE TRIGGER organization_sheet_initial_snapshot\n AFTER INSERT ON organization_sheet_bindings\n FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change();\n\nDO $$\nDECLARE table_name text;\nBEGIN\n FOREACH table_name IN ARRAY ARRAY[\n  'finance_orgs','finance_entries','finance_lines','finance_loans',\n  'finance_campaigns','finance_expenses','finance_payments','finance_proposals',\n  'finance_votes','finance_audit','savings_group_policies','savings_cycles',\n  'savings_rotation_rounds','savings_obligations','memberships','interventions'\n ] LOOP\n  EXECUTE format('CREATE TRIGGER organization_sheet_changed AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change()',table_name);\n END LOOP;\nEND;\n$$;\n\n-- Existing trusted bindings need their first snapshot as well.\nINSERT INTO organization_sheet_outbox(tenant_id,org_id)\n SELECT tenant_id,org_id FROM organization_sheet_bindings;\n",
  "008-personal-sheet-destinations.sql": "-- A user explicitly opts their submitted goals into one organization sheet.\n-- This stores routing consent only; there are no goal contents or credentials.\nALTER TABLE account_profiles ADD CONSTRAINT account_profiles_tenant_user_unique UNIQUE(tenant_id,user_id);\nCREATE TABLE personal_sheet_destinations (\n tenant_id text NOT NULL,\n user_id text NOT NULL,\n org_id text NOT NULL,\n created_at timestamptz NOT NULL DEFAULT now(),\n PRIMARY KEY(tenant_id,user_id),\n FOREIGN KEY(tenant_id,user_id) REFERENCES account_profiles(tenant_id,user_id) ON DELETE CASCADE,\n FOREIGN KEY(tenant_id,user_id,org_id) REFERENCES memberships(tenant_id,user_id,org_id) ON DELETE CASCADE,\n FOREIGN KEY(tenant_id,org_id) REFERENCES organization_sheet_bindings(tenant_id,org_id) ON DELETE CASCADE\n);\nCREATE TRIGGER personal_sheet_destination_changed\n AFTER INSERT OR UPDATE OR DELETE ON personal_sheet_destinations\n FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change();\n\nCREATE FUNCTION queue_personal_goal_sheet_change() RETURNS trigger\nLANGUAGE plpgsql AS $$\nDECLARE destination record;\nBEGIN\n IF TG_OP IN ('DELETE','UPDATE') THEN\n  FOR destination IN SELECT tenant_id,org_id FROM personal_sheet_destinations\n   WHERE tenant_id=OLD.tenant_id AND user_id=OLD.user_id LOOP\n   PERFORM enqueue_organization_sheet(destination.tenant_id,destination.org_id);\n  END LOOP;\n END IF;\n IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND (OLD.tenant_id,OLD.user_id) IS DISTINCT FROM (NEW.tenant_id,NEW.user_id)) THEN\n  FOR destination IN SELECT tenant_id,org_id FROM personal_sheet_destinations\n   WHERE tenant_id=NEW.tenant_id AND user_id=NEW.user_id LOOP\n   PERFORM enqueue_organization_sheet(destination.tenant_id,destination.org_id);\n  END LOOP;\n END IF;\n RETURN NULL;\nEND;\n$$;\nCREATE TRIGGER personal_goal_sheet_changed\n AFTER INSERT OR UPDATE OR DELETE ON goals\n FOR EACH ROW EXECUTE FUNCTION queue_personal_goal_sheet_change();\nCREATE TRIGGER personal_onboarding_sheet_changed\n AFTER INSERT OR UPDATE OR DELETE ON workspace_onboarding_requests\n FOR EACH ROW EXECUTE FUNCTION queue_personal_goal_sheet_change();\n\n-- A consented account name/email or active status change can alter the export.\n-- Credential fields and session tables never trigger or enter sheet payloads.\nCREATE FUNCTION queue_personal_account_sheet_change() RETURNS trigger\nLANGUAGE plpgsql AS $$\nDECLARE destination record; selected_user text;\nBEGIN\n IF TG_TABLE_NAME='app_users' THEN\n  IF (OLD.name,OLD.email) IS NOT DISTINCT FROM (NEW.name,NEW.email) THEN RETURN NULL; END IF;\n  selected_user=NEW.id;\n ELSE\n  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NULL; END IF;\n  selected_user=NEW.user_id;\n END IF;\n FOR destination IN SELECT tenant_id,org_id FROM personal_sheet_destinations WHERE user_id=selected_user LOOP\n  PERFORM enqueue_organization_sheet(destination.tenant_id,destination.org_id);\n END LOOP;\n RETURN NULL;\nEND;\n$$;\nCREATE TRIGGER personal_sheet_user_changed\n AFTER UPDATE OF name,email ON app_users\n FOR EACH ROW EXECUTE FUNCTION queue_personal_account_sheet_change();\nCREATE TRIGGER personal_sheet_profile_changed\n AFTER UPDATE OF status ON account_profiles\n FOR EACH ROW EXECUTE FUNCTION queue_personal_account_sheet_change();\n",
  "009-sheet-delivery-retries.sql": "-- Make retries durable and ensure added triggers also exist for databases that\n-- had already applied the preceding migrations before this update.\nALTER TABLE organization_sheet_outbox ADD COLUMN IF NOT EXISTS attempt_count integer NOT NULL DEFAULT 0;\nALTER TABLE organization_sheet_outbox ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE organization_sheet_outbox ADD COLUMN IF NOT EXISTS last_error_code text;\n\nCREATE OR REPLACE FUNCTION enqueue_organization_sheet(p_tenant text, p_org text) RETURNS void\nLANGUAGE plpgsql AS $$\nBEGIN\n PERFORM 1 FROM organization_sheet_bindings WHERE tenant_id=p_tenant AND org_id=p_org FOR SHARE;\n IF NOT FOUND THEN RETURN; END IF;\n INSERT INTO organization_sheet_outbox(tenant_id,org_id) VALUES(p_tenant,p_org)\n ON CONFLICT(tenant_id,org_id) DO UPDATE\n SET desired_revision=organization_sheet_outbox.desired_revision+1,\n     status='pending', updated_at=now(), next_attempt_at=now(),\n     attempt_count=0, last_error_code=NULL;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS organization_sheet_changed ON interventions;\nCREATE TRIGGER organization_sheet_changed AFTER INSERT OR UPDATE OR DELETE ON interventions\n FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change();\nDROP TRIGGER IF EXISTS personal_onboarding_sheet_changed ON workspace_onboarding_requests;\nCREATE TRIGGER personal_onboarding_sheet_changed AFTER INSERT OR UPDATE OR DELETE ON workspace_onboarding_requests\n FOR EACH ROW EXECUTE FUNCTION queue_personal_goal_sheet_change();\n\nCREATE OR REPLACE FUNCTION queue_personal_account_sheet_change() RETURNS trigger\nLANGUAGE plpgsql AS $$\nDECLARE destination record; selected_user text;\nBEGIN\n IF TG_TABLE_NAME='app_users' THEN\n  IF (OLD.name,OLD.email) IS NOT DISTINCT FROM (NEW.name,NEW.email) THEN RETURN NULL; END IF;\n  selected_user=NEW.id;\n ELSE\n  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NULL; END IF;\n  selected_user=NEW.user_id;\n END IF;\n FOR destination IN SELECT tenant_id,org_id FROM personal_sheet_destinations WHERE user_id=selected_user LOOP\n  PERFORM enqueue_organization_sheet(destination.tenant_id,destination.org_id);\n END LOOP;\n RETURN NULL;\nEND;\n$$;\nDROP TRIGGER IF EXISTS personal_sheet_user_changed ON app_users;\nCREATE TRIGGER personal_sheet_user_changed AFTER UPDATE OF name,email ON app_users\n FOR EACH ROW EXECUTE FUNCTION queue_personal_account_sheet_change();\nDROP TRIGGER IF EXISTS personal_sheet_profile_changed ON account_profiles;\nCREATE TRIGGER personal_sheet_profile_changed AFTER UPDATE OF status ON account_profiles\n FOR EACH ROW EXECUTE FUNCTION queue_personal_account_sheet_change();\n",
  "010-savings-group-administrator-label.sql": "-- Descriptive text entered at group setup; this label grants no authority.\nALTER TABLE savings_group_policies\n ADD COLUMN administrator_label text NOT NULL DEFAULT ''\n CHECK (char_length(administrator_label)<=120);\n",
  "011-ngo-sheet-bindings.sql": "-- Preserve a real composite finance-org FK for every non-NGO destination.\n-- NGO programs are not fabricated financial organizations.\nALTER TABLE organization_sheet_bindings\n ADD COLUMN financial_org_id text GENERATED ALWAYS AS\n  (CASE WHEN org_id='ngo-imizi' THEN NULL ELSE org_id END) STORED;\nALTER TABLE organization_sheet_bindings\n ADD CONSTRAINT organization_sheet_financial_org_fk\n FOREIGN KEY(tenant_id,financial_org_id) REFERENCES finance_orgs(tenant_id,org_id);\nALTER TABLE organization_sheet_bindings\n ADD CONSTRAINT organization_sheet_tenant_fk\n FOREIGN KEY(tenant_id) REFERENCES demo_tenants(id);\nALTER TABLE organization_sheet_bindings\n DROP CONSTRAINT organization_sheet_bindings_tenant_id_org_id_fkey;\n\n-- Fail safely rather than silently grandfathering any previously fabricated\n-- NGO financial organization binding without an exact active NGO administrator.\nDO $$\nBEGIN\n IF EXISTS(SELECT 1 FROM organization_sheet_bindings b WHERE b.org_id='ngo-imizi'\n  AND NOT EXISTS(SELECT 1 FROM memberships m\n   JOIN account_profiles p ON p.tenant_id=m.tenant_id AND p.user_id=m.user_id AND p.status='active'\n   JOIN app_users u ON u.id=m.user_id AND u.role='ngo'\n   WHERE m.tenant_id=b.tenant_id AND m.org_id=b.org_id AND m.role='ngo')) THEN\n  RAISE EXCEPTION 'Existing NGO binding requires an active administrator in the exact organization';\n END IF;\nEND;\n$$;\n\nCREATE FUNCTION validate_ngo_sheet_binding() RETURNS trigger\nLANGUAGE plpgsql AS $$\nDECLARE candidate record;\nBEGIN\n IF NEW.org_id<>'ngo-imizi' THEN RETURN NEW; END IF;\n FOR candidate IN SELECT m.user_id FROM memberships m\n  JOIN account_profiles p ON p.tenant_id=m.tenant_id AND p.user_id=m.user_id\n  WHERE m.tenant_id=NEW.tenant_id AND m.org_id=NEW.org_id\n   AND m.role='ngo' AND p.status='active' ORDER BY m.user_id LOOP\n  -- Match provisioning's profile -> account -> membership lock order.\n  PERFORM 1 FROM account_profiles WHERE tenant_id=NEW.tenant_id\n   AND user_id=candidate.user_id AND status='active' FOR SHARE;\n  IF NOT FOUND THEN CONTINUE; END IF;\n  PERFORM 1 FROM app_users WHERE id=candidate.user_id AND role='ngo' FOR SHARE;\n  IF NOT FOUND THEN CONTINUE; END IF;\n  PERFORM 1 FROM memberships WHERE tenant_id=NEW.tenant_id\n   AND org_id=NEW.org_id AND user_id=candidate.user_id AND role='ngo' FOR SHARE;\n  IF FOUND THEN RETURN NEW; END IF;\n END LOOP;\n RAISE EXCEPTION 'NGO sheet binding requires an active administrator in the exact organization';\nEND;\n$$;\nCREATE TRIGGER organization_sheet_ngo_guard BEFORE INSERT OR UPDATE\n ON organization_sheet_bindings FOR EACH ROW EXECUTE FUNCTION validate_ngo_sheet_binding();\n\n-- NGO spreadsheets contain interventions only, never personal/account records.\nALTER TABLE personal_sheet_destinations ADD CONSTRAINT personal_sheet_financial_destination_only\n CHECK(org_id<>'ngo-imizi');\n\nCREATE FUNCTION queue_organization_profile_status_change() RETURNS trigger\nLANGUAGE plpgsql AS $$\nDECLARE destination record;\nBEGIN\n IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NULL; END IF;\n FOR destination IN SELECT DISTINCT m.tenant_id,m.org_id FROM memberships m\n  JOIN organization_sheet_bindings b ON b.tenant_id=m.tenant_id AND b.org_id=m.org_id\n  WHERE m.tenant_id=NEW.tenant_id AND m.user_id=NEW.user_id\n  ORDER BY m.tenant_id,m.org_id LOOP\n  PERFORM enqueue_organization_sheet(destination.tenant_id,destination.org_id);\n END LOOP;\n RETURN NULL;\nEND;\n$$;\nCREATE TRIGGER organization_sheet_profile_status_changed AFTER UPDATE OF status\n ON account_profiles FOR EACH ROW EXECUTE FUNCTION queue_organization_profile_status_change();\n",
  "012-dedicated-workspace.sql": "ALTER TABLE account_profiles ADD COLUMN IF NOT EXISTS workspace text;\n",
  "013-savings-group-roles-and-expenses.sql": "-- Migration 013: Savings Group Leadership Roles & Expense Accounting\n\n-- 1. Extend app_users role check to include 'accountant' and 'secretary'\nALTER TABLE app_users DROP CONSTRAINT IF EXISTS app_users_role_check;\nALTER TABLE app_users ADD CONSTRAINT app_users_role_check CHECK(role IN ('member','president','treasurer','accountant','secretary','cooperative','ngo'));\n\n-- 1b. Extend finance_payments kind check to include 'income'\nALTER TABLE finance_payments DROP CONSTRAINT IF EXISTS finance_payments_kind_check;\nALTER TABLE finance_payments ADD CONSTRAINT finance_payments_kind_check CHECK(kind IN ('contribution','loan','repayment','donation','expense','group-payout','share-out','income'));\n\n-- 2. Role assignment history\nCREATE TABLE IF NOT EXISTS savings_group_role_history (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  user_id text NOT NULL,\n  old_role text NOT NULL,\n  new_role text NOT NULL,\n  assigned_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 3. Expense categories for savings groups\nCREATE TABLE IF NOT EXISTS savings_group_expense_categories (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id),\n  UNIQUE(tenant_id, org_id, name)\n);\n\n-- 4. Savings group expenses with approval workflow and receipt attachments\nCREATE TABLE IF NOT EXISTS savings_group_expenses (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  category text NOT NULL,\n  title text NOT NULL,\n  description text,\n  amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991),\n  receipt_attachment text,\n  status text NOT NULL DEFAULT 'recorded' CHECK(status IN ('recorded','approved','declined','paid','failed')),\n  recorded_by text NOT NULL,\n  approved_by text,\n  approved_at timestamptz,\n  payment_reference text,\n  journal_id text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n",
  "014-cooperative-management.sql": "-- Migration 014: Cooperative Management, Financial Governance & Member Value Engine\n\n-- 1. Cooperative Profiles & Bylaw Policies\nCREATE TABLE IF NOT EXISTS cooperative_profiles (\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  category text NOT NULL DEFAULT 'agriculture' CHECK(category IN ('agriculture','processing','service','commercial','multipurpose')),\n  sector text NOT NULL DEFAULT '',\n  registration_number text,\n  nominal_share_value bigint NOT NULL DEFAULT 10000 CHECK(nominal_share_value > 0 AND nominal_share_value <= 9007199254740991),\n  min_shares_per_member integer NOT NULL DEFAULT 5 CHECK(min_shares_per_member >= 1),\n  max_shares_per_member integer DEFAULT 1000 CHECK(max_shares_per_member >= 1),\n  statutory_reserve_bps integer NOT NULL DEFAULT 2000 CHECK(statutory_reserve_bps BETWEEN 0 AND 10000),\n  social_fund_bps integer NOT NULL DEFAULT 1000 CHECK(social_fund_bps BETWEEN 0 AND 10000),\n  dividend_pool_bps integer NOT NULL DEFAULT 4000 CHECK(dividend_pool_bps BETWEEN 0 AND 10000),\n  bonus_pool_bps integer NOT NULL DEFAULT 6000 CHECK(bonus_pool_bps BETWEEN 0 AND 10000),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY(tenant_id, org_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 2. Staff and Governance Appointments\nCREATE TABLE IF NOT EXISTS cooperative_staff_appointments (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  user_id text NOT NULL,\n  title text NOT NULL,\n  department text NOT NULL DEFAULT 'Administration',\n  appointed_at date NOT NULL DEFAULT CURRENT_DATE,\n  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','resigned')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 3. Member Share Accounts (Subscribed vs Paid vs Outstanding)\nCREATE TABLE IF NOT EXISTS cooperative_share_accounts (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  user_id text NOT NULL,\n  shares_subscribed integer NOT NULL DEFAULT 0 CHECK(shares_subscribed >= 0),\n  shares_paid integer NOT NULL DEFAULT 0 CHECK(shares_paid >= 0 AND shares_paid <= shares_subscribed),\n  amount_subscribed bigint NOT NULL DEFAULT 0 CHECK(amount_subscribed >= 0 AND amount_subscribed <= 9007199254740991),\n  amount_paid bigint NOT NULL DEFAULT 0 CHECK(amount_paid >= 0 AND amount_paid <= 9007199254740991),\n  amount_outstanding bigint NOT NULL DEFAULT 0 CHECK(amount_outstanding >= 0 AND amount_outstanding <= 9007199254740991),\n  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','pending','suspended','transferred')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, user_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 4. Share Transactions (Subscriptions, Payments, Transfers)\nCREATE TABLE IF NOT EXISTS cooperative_share_transactions (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  user_id text NOT NULL,\n  kind text NOT NULL CHECK(kind IN ('subscription','payment','transfer','refund')),\n  shares integer NOT NULL CHECK(shares > 0),\n  amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991),\n  payment_reference text,\n  journal_id text,\n  status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('recorded','confirmed','cancelled')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 5. Production Deliveries (Member Agricultural / Product Deliveries)\nCREATE TABLE IF NOT EXISTS cooperative_deliveries (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  user_id text NOT NULL,\n  product_name text NOT NULL,\n  category text NOT NULL DEFAULT 'grain' CHECK(category IN ('grain','horticulture','coffee','dairy','tea','other')),\n  quantity bigint NOT NULL CHECK(quantity > 0 AND quantity <= 9007199254740991),\n  unit text NOT NULL DEFAULT 'kg' CHECK(unit IN ('kg','liter','bag','crate','ton')),\n  grade text NOT NULL DEFAULT 'Grade A' CHECK(grade IN ('Grade A','Grade B','Standard')),\n  unit_price bigint NOT NULL CHECK(unit_price > 0 AND unit_price <= 9007199254740991),\n  total_value bigint NOT NULL CHECK(total_value > 0 AND total_value <= 9007199254740991),\n  payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','approved','paid','cancelled')),\n  payment_reference text,\n  delivery_date date NOT NULL DEFAULT CURRENT_DATE,\n  notes text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 6. Commercial Sales & Receivables (Cooperative Selling to Buyers)\nCREATE TABLE IF NOT EXISTS cooperative_sales (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  buyer_name text NOT NULL,\n  product_name text NOT NULL,\n  quantity bigint NOT NULL CHECK(quantity > 0 AND quantity <= 9007199254740991),\n  unit text NOT NULL DEFAULT 'kg',\n  unit_price bigint NOT NULL CHECK(unit_price > 0 AND unit_price <= 9007199254740991),\n  total_amount bigint NOT NULL CHECK(total_amount > 0 AND total_amount <= 9007199254740991),\n  payment_status text NOT NULL DEFAULT 'invoiced' CHECK(payment_status IN ('invoiced','paid','overdue','cancelled')),\n  payment_reference text,\n  sale_date date NOT NULL DEFAULT CURRENT_DATE,\n  journal_id text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 7. Surplus Allocations (Period Close & Allocation Calculations)\nCREATE TABLE IF NOT EXISTS cooperative_surplus_allocations (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  period_label text NOT NULL,\n  gross_revenue bigint NOT NULL DEFAULT 0 CHECK(gross_revenue >= 0 AND gross_revenue <= 9007199254740991),\n  total_expenses bigint NOT NULL DEFAULT 0 CHECK(total_expenses >= 0 AND total_expenses <= 9007199254740991),\n  net_surplus bigint NOT NULL DEFAULT 0 CHECK(net_surplus >= 0 AND net_surplus <= 9007199254740991),\n  statutory_reserve_amount bigint NOT NULL DEFAULT 0 CHECK(statutory_reserve_amount >= 0),\n  social_fund_amount bigint NOT NULL DEFAULT 0 CHECK(social_fund_amount >= 0),\n  distributable_surplus bigint NOT NULL DEFAULT 0 CHECK(distributable_surplus >= 0),\n  dividend_pool bigint NOT NULL DEFAULT 0 CHECK(dividend_pool >= 0),\n  bonus_pool bigint NOT NULL DEFAULT 0 CHECK(bonus_pool >= 0),\n  status text NOT NULL DEFAULT 'calculated' CHECK(status IN ('calculated','approved_by_assembly','distributed')),\n  resolution_ref text,\n  approved_by text,\n  approved_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 8. Member Value Distributions (Individual Dividends & Patronage Bonuses)\nCREATE TABLE IF NOT EXISTS cooperative_member_distributions (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  allocation_id text NOT NULL REFERENCES cooperative_surplus_allocations(id),\n  user_id text NOT NULL,\n  shares_held integer NOT NULL DEFAULT 0 CHECK(shares_held >= 0),\n  share_ratio_bps integer NOT NULL DEFAULT 0 CHECK(share_ratio_bps >= 0 AND share_ratio_bps <= 10000),\n  dividend_amount bigint NOT NULL DEFAULT 0 CHECK(dividend_amount >= 0),\n  participation_units bigint NOT NULL DEFAULT 0 CHECK(participation_units >= 0),\n  participation_ratio_bps integer NOT NULL DEFAULT 0 CHECK(participation_ratio_bps >= 0 AND participation_ratio_bps <= 10000),\n  bonus_amount bigint NOT NULL DEFAULT 0 CHECK(bonus_amount >= 0),\n  total_entitlement bigint NOT NULL DEFAULT 0 CHECK(total_entitlement >= 0),\n  payout_status text NOT NULL DEFAULT 'entitled' CHECK(payout_status IN ('entitled','pending','paid')),\n  payout_reference text,\n  paid_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 9. Investment Guardian Proposals & Digital Twin Scenarios\nCREATE TABLE IF NOT EXISTS cooperative_investments (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  title text NOT NULL,\n  category text NOT NULL DEFAULT 'equipment' CHECK(category IN ('processing','logistics','storage','equipment','energy','infrastructure')),\n  capital_cost bigint NOT NULL CHECK(capital_cost > 0 AND capital_cost <= 9007199254740991),\n  monthly_operating_cost bigint NOT NULL DEFAULT 0 CHECK(monthly_operating_cost >= 0),\n  expected_monthly_benefit bigint NOT NULL DEFAULT 0 CHECK(expected_monthly_benefit >= 0),\n  useful_life_months integer NOT NULL DEFAULT 60 CHECK(useful_life_months > 0),\n  financing_source text NOT NULL DEFAULT 'cash_reserve' CHECK(financing_source IN ('cash_reserve','member_levy','commercial_loan')),\n  status text NOT NULL DEFAULT 'simulated' CHECK(status IN ('draft','simulated','board_approved','assembly_approved','purchased','rejected')),\n  guardian_verdict text NOT NULL DEFAULT 'sustainable' CHECK(guardian_verdict IN ('sustainable','caution','critical_liquidity')),\n  payback_months integer NOT NULL DEFAULT 0,\n  created_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 10. Governance Meetings & Assembly Resolutions\nCREATE TABLE IF NOT EXISTS cooperative_governance_events (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  event_type text NOT NULL CHECK(event_type IN ('board_meeting','general_assembly','supervisory_audit')),\n  title text NOT NULL,\n  meeting_date date NOT NULL DEFAULT CURRENT_DATE,\n  agenda text NOT NULL,\n  resolutions text NOT NULL,\n  recorded_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n",
  "015-fundraising-platform.sql": "-- Migration 015: HURIZA Fund — Social Fundraising, Campaign Pages, Contributions & TrustFlow Transparency\n\n-- 1. Extended Campaign Profiles, Themes & Granular Visibility Policies\nCREATE TABLE IF NOT EXISTS fundraising_campaign_profiles (\n  campaign_id text PRIMARY KEY REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  slug text NOT NULL,\n  family text NOT NULL DEFAULT 'causes' CHECK (family IN ('moments','causes','community')),\n  subcategory text NOT NULL DEFAULT 'charity',\n  theme text NOT NULL DEFAULT 'classic_blue' CHECK (theme IN ('wedding_elegant','birthday_celebration','medical_trust','charity_warm','community_impact','classic_blue')),\n  organizer_user_id text NOT NULL,\n  organizer_name text NOT NULL,\n  beneficiary_name text NOT NULL DEFAULT '',\n  beneficiary_type text NOT NULL DEFAULT 'community' CHECK (beneficiary_type IN ('self','individual','family','child_protected','community','organization')),\n  location text NOT NULL DEFAULT 'Kigali, Rwanda',\n  event_date date,\n  start_date date NOT NULL DEFAULT CURRENT_DATE,\n  story text NOT NULL DEFAULT '',\n  cover_image_url text NOT NULL DEFAULT '',\n  video_url text NOT NULL DEFAULT '',\n  visibility text NOT NULL DEFAULT 'public' CHECK (visibility IN ('public','unlisted','private')),\n  stats_visibility text NOT NULL DEFAULT 'everyone' CHECK (stats_visibility IN ('everyone','contributors_only','selected_contributors','team_only')),\n  goal_visibility text NOT NULL DEFAULT 'everyone' CHECK (goal_visibility IN ('everyone','contributors_only','selected_contributors','team_only')),\n  raised_visibility text NOT NULL DEFAULT 'everyone' CHECK (raised_visibility IN ('everyone','contributors_only','selected_contributors','team_only')),\n  contributors_visibility text NOT NULL DEFAULT 'everyone' CHECK (contributors_visibility IN ('everyone','contributors_only','selected_contributors','team_only')),\n  spending_visibility text NOT NULL DEFAULT 'everyone' CHECK (spending_visibility IN ('everyone','contributors_only','selected_contributors','team_only')),\n  allow_comments boolean NOT NULL DEFAULT true,\n  allow_anonymous boolean NOT NULL DEFAULT true,\n  allow_rsvp boolean NOT NULL DEFAULT false,\n  suggested_amounts text NOT NULL DEFAULT '5000,10000,25000,50000',\n  verification_status text NOT NULL DEFAULT 'unverified' CHECK (verification_status IN ('unverified','pending_review','verified_demo','requires_review','suspended')),\n  verification_notes text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, slug),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\nCREATE INDEX IF NOT EXISTS fundraising_campaign_profiles_slug_idx ON fundraising_campaign_profiles(slug);\nCREATE INDEX IF NOT EXISTS fundraising_campaign_profiles_scope_idx ON fundraising_campaign_profiles(tenant_id, org_id, visibility);\n\n-- 2. Campaign Media Gallery & Documents\nCREATE TABLE IF NOT EXISTS fundraising_campaign_media (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  media_type text NOT NULL DEFAULT 'gallery' CHECK (media_type IN ('cover','gallery','video','document')),\n  url text NOT NULL,\n  caption text NOT NULL DEFAULT '',\n  sort_order integer NOT NULL DEFAULT 0,\n  uploaded_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 3. Organizer Social Updates & Progress Feed\nCREATE TABLE IF NOT EXISTS fundraising_campaign_updates (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  update_type text NOT NULL DEFAULT 'progress' CHECK (update_type IN ('progress','milestone','thank_you','announcement','spending','photo')),\n  title text NOT NULL,\n  body text NOT NULL,\n  media_url text NOT NULL DEFAULT '',\n  author_id text NOT NULL,\n  author_name text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 4. Supporter Comments, Guestbook & Congratulatory Messages\nCREATE TABLE IF NOT EXISTS fundraising_comments (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  update_id text,\n  author_id text NOT NULL,\n  author_name text NOT NULL,\n  is_anonymous boolean NOT NULL DEFAULT false,\n  comment_type text NOT NULL DEFAULT 'comment' CHECK (comment_type IN ('comment','guestbook','congratulation','dedication')),\n  message text NOT NULL,\n  reaction text NOT NULL DEFAULT 'heart',\n  status text NOT NULL DEFAULT 'visible' CHECK (status IN ('visible','hidden')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 5. Supporter Reactions\nCREATE TABLE IF NOT EXISTS fundraising_reactions (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  target_type text NOT NULL DEFAULT 'campaign' CHECK (target_type IN ('campaign','update')),\n  target_id text NOT NULL,\n  user_id text NOT NULL,\n  reaction_type text NOT NULL DEFAULT 'heart' CHECK (reaction_type IN ('heart','celebrate','pray','clap','star')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, campaign_id, target_type, target_id, user_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 6. Campaign Followers\nCREATE TABLE IF NOT EXISTS fundraising_followers (\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  user_id text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY(tenant_id, org_id, campaign_id, user_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 7. Contributions, Pledges & Supporter Privacy Preferences\nCREATE TABLE IF NOT EXISTS fundraising_contributions (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  payment_id text REFERENCES finance_payments(id),\n  user_id text NOT NULL,\n  contributor_name text NOT NULL,\n  display_preference text NOT NULL DEFAULT 'public_name' CHECK (display_preference IN ('public_name','display_name','anonymous')),\n  custom_display_name text NOT NULL DEFAULT '',\n  amount bigint NOT NULL CHECK (amount > 0 AND amount <= 9007199254740991),\n  contribution_type text NOT NULL DEFAULT 'one_time' CHECK (contribution_type IN ('one_time','recurring_simulated','pledge','gift_item')),\n  channel text NOT NULL DEFAULT 'mtn_momo' CHECK (channel IN ('mtn_momo','airtel_money','card_simulated')),\n  status text NOT NULL CHECK (status IN ('success','pending','failed','unknown','pledged','refunded')),\n  reference text NOT NULL,\n  message text NOT NULL DEFAULT '',\n  dedication text NOT NULL DEFAULT '',\n  gift_item_id text,\n  team_id text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, reference),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 8. Database-Backed Access Grants (Selected Contributors & Private Invitations)\nCREATE TABLE IF NOT EXISTS fundraising_access_grants (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  user_id text NOT NULL,\n  user_name text NOT NULL DEFAULT '',\n  grant_type text NOT NULL DEFAULT 'selected_stats' CHECK (grant_type IN ('campaign_view','selected_stats','full_transparency')),\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),\n  granted_by text NOT NULL,\n  expires_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, campaign_id, user_id, grant_type),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 9. Campaign Organizing Team & Role Assignments\nCREATE TABLE IF NOT EXISTS fundraising_team_members (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  user_id text NOT NULL,\n  user_name text NOT NULL,\n  campaign_role text NOT NULL CHECK (campaign_role IN ('owner','co_organizer','accountant','treasurer','approver','content_manager','team_captain')),\n  team_name text NOT NULL DEFAULT '',\n  assigned_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, campaign_id, user_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 10. Campaign Milestones & Outcome Tracking\nCREATE TABLE IF NOT EXISTS fundraising_milestones (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  description text NOT NULL DEFAULT '',\n  target_amount bigint NOT NULL CHECK (target_amount > 0 AND target_amount <= 9007199254740991),\n  allocated_amount bigint NOT NULL DEFAULT 0 CHECK (allocated_amount >= 0 AND allocated_amount <= 9007199254740991),\n  spent_amount bigint NOT NULL DEFAULT 0 CHECK (spent_amount >= 0 AND spent_amount <= 9007199254740991),\n  outcome_status text NOT NULL DEFAULT 'planned' CHECK (outcome_status IN ('planned','in_progress','funded_pending_execution','completed_verified')),\n  outcome_evidence text NOT NULL DEFAULT '',\n  sort_order integer NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 11. TrustFlow Expense Details (Accountant Metadata Linked to finance_expenses)\nCREATE TABLE IF NOT EXISTS fundraising_expense_details (\n  expense_id text PRIMARY KEY REFERENCES finance_expenses(id) ON DELETE CASCADE,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  category text NOT NULL DEFAULT 'Program Execution',\n  description text NOT NULL DEFAULT '',\n  vendor_name text NOT NULL DEFAULT '',\n  receipt_url text NOT NULL DEFAULT '',\n  milestone_id text,\n  payment_reference text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 12. Wedding & Birthday Gift Registry / Group Gift Goals\nCREATE TABLE IF NOT EXISTS fundraising_gift_items (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  description text NOT NULL DEFAULT '',\n  target_amount bigint NOT NULL CHECK (target_amount > 0 AND target_amount <= 9007199254740991),\n  contributed_amount bigint NOT NULL DEFAULT 0 CHECK (contributed_amount >= 0 AND contributed_amount <= 9007199254740991),\n  image_url text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','partially_funded','fulfilled')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 13. Event RSVPs for Moments Campaigns\nCREATE TABLE IF NOT EXISTS fundraising_rsvps (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  user_id text NOT NULL,\n  guest_name text NOT NULL,\n  attendance_status text NOT NULL DEFAULT 'attending' CHECK (attendance_status IN ('attending','maybe','declined')),\n  guests_count integer NOT NULL DEFAULT 1 CHECK (guests_count BETWEEN 1 AND 10),\n  dietary_or_note text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tenant_id, org_id, campaign_id, user_id),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 14. Sponsor Matching Pledges\nCREATE TABLE IF NOT EXISTS fundraising_matching_pledges (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  sponsor_name text NOT NULL,\n  pledged_amount bigint NOT NULL CHECK (pledged_amount > 0 AND pledged_amount <= 9007199254740991),\n  confirmed_amount bigint NOT NULL DEFAULT 0 CHECK (confirmed_amount >= 0 AND confirmed_amount <= pledged_amount),\n  match_ratio_bps integer NOT NULL DEFAULT 10000 CHECK (match_ratio_bps BETWEEN 1000 AND 10000),\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','fulfilled','expired')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- 15. Safety, Verification & Moderation Events\nCREATE TABLE IF NOT EXISTS fundraising_moderation_events (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL,\n  org_id text NOT NULL,\n  campaign_id text NOT NULL REFERENCES finance_campaigns(id) ON DELETE CASCADE,\n  actor_id text NOT NULL,\n  event_type text NOT NULL CHECK (event_type IN ('report_submitted','verification_updated','campaign_suspended','campaign_restored','comment_moderated','privacy_warning_acknowledged')),\n  reason text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY(tenant_id, org_id) REFERENCES finance_orgs(tenant_id, org_id)\n);\n\n-- Attach Google Sheets outbox change triggers so fundraising changes sync automatically\nDO $$\nDECLARE table_name text;\nBEGIN\n  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'queue_organization_sheet_change') THEN\n    FOREACH table_name IN ARRAY ARRAY[\n      'fundraising_campaign_profiles','fundraising_campaign_updates','fundraising_contributions',\n      'fundraising_milestones','fundraising_expense_details','fundraising_matching_pledges'\n    ] LOOP\n      EXECUTE format('DROP TRIGGER IF EXISTS organization_sheet_changed ON %I', table_name);\n      EXECUTE format('CREATE TRIGGER organization_sheet_changed AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change()', table_name);\n    END LOOP;\n  END IF;\nEND;\n$$;\n",
  "016-ngo-impact-platform.sql": "-- HURIZA IMPACT — OPERATION INSTITUTIONAL INTELLIGENCE\n-- NGO Management, Grants, Field Operations, Monitoring & Evaluation (MEAL),\n-- ImpactTrace, and Donor Accountability Platform\n\nCREATE TABLE ngo_profiles (\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  name text NOT NULL,\n  ngo_type text NOT NULL DEFAULT 'national_ngo' CHECK (ngo_type IN ('local_ngo','national_ngo','international_ngo','foundation','faith_based','social_enterprise','government_program','research_partner')),\n  designation text NOT NULL DEFAULT 'National Financial Inclusion & Community Development Partner',\n  mission text NOT NULL DEFAULT '',\n  focus_sectors text NOT NULL DEFAULT '[\"financial_inclusion\",\"savings_groups\",\"cooperative_strengthening\",\"women_youth_empowerment\"]',\n  operating_districts text NOT NULL DEFAULT '[\"Gasabo\",\"Kicukiro\",\"Rulindo\",\"Rwamagana\",\"Huye\"]',\n  contact_email text NOT NULL DEFAULT 'programs@cgi-rwanda.org',\n  contact_phone text NOT NULL DEFAULT '+250 788 310 400',\n  website text NOT NULL DEFAULT 'https://cgi-rwanda.org',\n  registration_ref text NOT NULL DEFAULT 'RGB/NGO/2021/0418',\n  reporting_period text NOT NULL DEFAULT 'quarterly' CHECK (reporting_period IN ('monthly','quarterly','semi_annual','annual')),\n  approval_threshold_rwf bigint NOT NULL DEFAULT 500000 CHECK (approval_threshold_rwf >= 0),\n  data_retention_months integer NOT NULL DEFAULT 60 CHECK (data_retention_months >= 6),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, org_id)\n);\n\nCREATE TABLE ngo_staff_members (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  user_id text NOT NULL,\n  full_name text NOT NULL,\n  email text NOT NULL DEFAULT '',\n  phone text NOT NULL DEFAULT '',\n  ngo_role text NOT NULL CHECK (ngo_role IN ('country_director','program_director','program_manager','project_officer','field_officer','meal_officer','finance_manager','accountant','grants_officer','safeguarding_officer','donor_viewer','partner_user','auditor','super_admin')),\n  assigned_program_id text NOT NULL DEFAULT 'all',\n  department text NOT NULL DEFAULT 'Programs & Field Operations',\n  location_district text NOT NULL DEFAULT 'Gasabo',\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','invited','suspended','inactive')),\n  assigned_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_programs (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  code text NOT NULL,\n  name text NOT NULL,\n  description text NOT NULL DEFAULT '',\n  objective text NOT NULL DEFAULT '',\n  target_population text NOT NULL DEFAULT '',\n  districts text NOT NULL DEFAULT '[]',\n  start_date text NOT NULL,\n  end_date text NOT NULL,\n  funding_source text NOT NULL DEFAULT '',\n  total_budget bigint NOT NULL DEFAULT 0 CHECK (total_budget >= 0),\n  lead_officer text NOT NULL DEFAULT '',\n  partner_orgs text NOT NULL DEFAULT '[]',\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('planning','active','completed','on_hold','closed')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_projects (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  code text NOT NULL,\n  name text NOT NULL,\n  district text NOT NULL,\n  sector text NOT NULL DEFAULT '',\n  site_name text NOT NULL DEFAULT '',\n  budget_allocated bigint NOT NULL DEFAULT 0 CHECK (budget_allocated >= 0),\n  budget_spent bigint NOT NULL DEFAULT 0 CHECK (budget_spent >= 0),\n  lead_officer text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('planning','active','completed','paused')),\n  start_date text NOT NULL,\n  end_date text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_grants (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  donor_name text NOT NULL,\n  grant_code text NOT NULL,\n  title text NOT NULL,\n  currency text NOT NULL DEFAULT 'RWF' CHECK (currency IN ('RWF','USD','EUR','GBP')),\n  original_amount bigint NOT NULL CHECK (original_amount >= 0),\n  exchange_rate_rwf bigint NOT NULL DEFAULT 1 CHECK (exchange_rate_rwf > 0),\n  award_amount_rwf bigint NOT NULL CHECK (award_amount_rwf >= 0),\n  received_amount_rwf bigint NOT NULL DEFAULT 0 CHECK (received_amount_rwf >= 0),\n  approved_budget_rwf bigint NOT NULL DEFAULT 0 CHECK (approved_budget_rwf >= 0),\n  restricted_categories text NOT NULL DEFAULT '[]',\n  start_date text NOT NULL,\n  end_date text NOT NULL,\n  next_report_due text NOT NULL DEFAULT '',\n  reporting_schedule text NOT NULL DEFAULT 'Quarterly financial & MEAL narrative',\n  conditions_note text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('pipeline','active','reporting_due','closing','closed')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_budget_lines (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  grant_id text NOT NULL REFERENCES ngo_grants(id) ON DELETE CASCADE,\n  category text NOT NULL CHECK (category IN ('savings_group_capacity','cooperative_support','field_operations','training_materials','monitoring_evaluation','digital_inclusion','safeguarding','personnel_admin','contingency')),\n  line_code text NOT NULL,\n  description text NOT NULL,\n  allocated_amount bigint NOT NULL CHECK (allocated_amount >= 0),\n  committed_amount bigint NOT NULL DEFAULT 0 CHECK (committed_amount >= 0),\n  spent_amount bigint NOT NULL DEFAULT 0 CHECK (spent_amount >= 0),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_activities (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  project_id text,\n  grant_id text,\n  budget_line_id text,\n  title text NOT NULL,\n  activity_type text NOT NULL CHECK (activity_type IN ('group_training','cooperative_advisory','seed_kit_distribution','digital_ledger_onboarding','field_monitoring','safeguarding_clinic','community_dialogue','baseline_survey')),\n  district text NOT NULL,\n  sector text NOT NULL DEFAULT '',\n  scheduled_date text NOT NULL,\n  completed_date text NOT NULL DEFAULT '',\n  lead_officer text NOT NULL DEFAULT '',\n  target_participants integer NOT NULL DEFAULT 0 CHECK (target_participants >= 0),\n  actual_participants integer NOT NULL DEFAULT 0 CHECK (actual_participants >= 0),\n  linked_entity_type text NOT NULL DEFAULT 'savings_group' CHECK (linked_entity_type IN ('savings_group','cooperative','fund_campaign','household_cohort','community_org')),\n  linked_entity_id text NOT NULL DEFAULT '',\n  evidence_url text NOT NULL DEFAULT '',\n  evidence_note text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','in_progress','completed','delayed','cancelled')),\n  verification_status text NOT NULL DEFAULT 'submitted' CHECK (verification_status IN ('submitted','meal_reviewed','approved','flagged')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_expenses (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  project_id text,\n  grant_id text NOT NULL REFERENCES ngo_grants(id) ON DELETE CASCADE,\n  budget_line_id text NOT NULL REFERENCES ngo_budget_lines(id) ON DELETE CASCADE,\n  activity_id text,\n  title text NOT NULL,\n  category text NOT NULL,\n  vendor_name text NOT NULL DEFAULT '',\n  amount bigint NOT NULL CHECK (amount > 0),\n  currency text NOT NULL DEFAULT 'RWF',\n  receipt_url text NOT NULL DEFAULT '',\n  description text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','program_reviewed','finance_approved','paid','rejected','reversed')),\n  requested_by text NOT NULL,\n  reviewed_by text NOT NULL DEFAULT '',\n  approved_by text NOT NULL DEFAULT '',\n  payment_reference text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_beneficiary_cohorts (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  cohort_code text NOT NULL,\n  name text NOT NULL,\n  cohort_type text NOT NULL CHECK (cohort_type IN ('savings_group_itsinda','savings_group_ikimina','cooperative','household_cluster','youth_enterprise','women_collective')),\n  district text NOT NULL,\n  sector text NOT NULL DEFAULT '',\n  linked_org_id text NOT NULL DEFAULT '',\n  households_count integer NOT NULL DEFAULT 0 CHECK (households_count >= 0),\n  participants_count integer NOT NULL DEFAULT 0 CHECK (participants_count >= 0),\n  female_count integer NOT NULL DEFAULT 0 CHECK (female_count >= 0),\n  youth_count integer NOT NULL DEFAULT 0 CHECK (youth_count >= 0),\n  enrollment_stage text NOT NULL DEFAULT 'active' CHECK (enrollment_stage IN ('registered','enrolled','active','graduated','inactive')),\n  safeguarding_level text NOT NULL DEFAULT 'standard' CHECK (safeguarding_level IN ('standard','protected_youth','high_confidentiality')),\n  consent_basis text NOT NULL DEFAULT 'informed_program_consent',\n  assigned_officer text NOT NULL DEFAULT '',\n  notes text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_field_visits (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  activity_id text,\n  officer_id text NOT NULL,\n  officer_name text NOT NULL,\n  visit_date text NOT NULL,\n  district text NOT NULL,\n  sector text NOT NULL DEFAULT '',\n  community_name text NOT NULL DEFAULT '',\n  purpose text NOT NULL,\n  form_type text NOT NULL DEFAULT 'savings_group_monitoring' CHECK (form_type IN ('group_registration','training_attendance','savings_group_monitoring','cooperative_support_visit','beneficiary_enrollment','follow_up_assessment')),\n  attendees_count integer NOT NULL DEFAULT 0 CHECK (attendees_count >= 0),\n  observations text NOT NULL DEFAULT '',\n  outcomes_recorded text NOT NULL DEFAULT '',\n  follow_up_needed text NOT NULL DEFAULT '',\n  evidence_attachment text NOT NULL DEFAULT '',\n  sync_status text NOT NULL DEFAULT 'synced' CHECK (sync_status IN ('queued_offline','synced','verified')),\n  verification_status text NOT NULL DEFAULT 'submitted' CHECK (verification_status IN ('submitted','meal_reviewed','approved','flagged')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_indicators (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  code text NOT NULL,\n  name text NOT NULL,\n  level text NOT NULL CHECK (level IN ('input','activity','output','outcome','impact_context')),\n  unit text NOT NULL DEFAULT 'count' CHECK (unit IN ('count','percentage','rwf','groups','cooperatives','households')),\n  baseline_value bigint NOT NULL DEFAULT 0,\n  target_value bigint NOT NULL DEFAULT 0,\n  current_value bigint NOT NULL DEFAULT 0,\n  numerator_label text NOT NULL DEFAULT '',\n  denominator_label text NOT NULL DEFAULT '',\n  data_source text NOT NULL DEFAULT '',\n  disaggregation text NOT NULL DEFAULT '{}',\n  reporting_period text NOT NULL DEFAULT '2026-Q2',\n  responsible_officer text NOT NULL DEFAULT '',\n  verification_status text NOT NULL DEFAULT 'submitted' CHECK (verification_status IN ('submitted','meal_reviewed','approved','flagged')),\n  methodology_note text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_data_quality_issues (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  issue_type text NOT NULL CHECK (issue_type IN ('missing_evidence','duplicate_beneficiary','unverified_indicator','overdue_group_report','budget_variance','missing_consent')),\n  severity text NOT NULL DEFAULT 'warning' CHECK (severity IN ('info','warning','critical')),\n  record_ref text NOT NULL,\n  description text NOT NULL,\n  resolution_note text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_review','resolved','dismissed')),\n  detected_by text NOT NULL DEFAULT 'HURIZA Data Quality Guardian',\n  resolved_by text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_report_snapshots (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  grant_id text,\n  title text NOT NULL,\n  report_type text NOT NULL CHECK (report_type IN ('donor_quarterly','rgb_compliance','district_partner','annual_impact','audit_pack')),\n  reporting_period text NOT NULL,\n  executive_summary text NOT NULL,\n  activities_summary text NOT NULL DEFAULT '',\n  indicators_snapshot text NOT NULL DEFAULT '[]',\n  budget_summary text NOT NULL DEFAULT '{}',\n  risks_and_limitations text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','reviewed','approved')),\n  prepared_by text NOT NULL,\n  approved_by text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE ngo_donor_access_grants (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  org_id text NOT NULL DEFAULT 'ngo-imizi',\n  program_id text NOT NULL REFERENCES ngo_programs(id) ON DELETE CASCADE,\n  grant_id text,\n  donor_name text NOT NULL,\n  donor_email text NOT NULL,\n  access_code text NOT NULL,\n  permissions_scope text NOT NULL DEFAULT 'aggregates_and_reports' CHECK (permissions_scope IN ('aggregates_only','aggregates_and_reports','full_grant_financials')),\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked','expired')),\n  expires_at text NOT NULL DEFAULT '2026-12-31',\n  granted_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nDO $$\nDECLARE table_name text;\nBEGIN\n  FOREACH table_name IN ARRAY ARRAY[\n    'ngo_profiles','ngo_staff_members','ngo_programs','ngo_projects',\n    'ngo_grants','ngo_budget_lines','ngo_activities','ngo_expenses',\n    'ngo_beneficiary_cohorts','ngo_field_visits','ngo_indicators',\n    'ngo_data_quality_issues','ngo_report_snapshots','ngo_donor_access_grants'\n  ] LOOP\n    EXECUTE format(\n      'CREATE TRIGGER organization_sheet_changed AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION queue_organization_sheet_change()',\n      table_name\n    );\n  END LOOP;\nEND;\n$$;\n",
  "017-personal-finance-extensions.sql": "-- Migration 017: Personal Finance Extensions\n-- Wallets & Accounts, Personal Loans & IOUs, and Investment Planning\n\nCREATE TABLE IF NOT EXISTS personal_wallets (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  user_id text NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,\n  institution text NOT NULL,\n  account_name text NOT NULL,\n  account_type text NOT NULL CHECK (account_type IN ('mobile_money','bank','sacco','cash','investment','other')),\n  account_identifier text NOT NULL DEFAULT '',\n  balance bigint NOT NULL DEFAULT 0 CHECK (balance >= 0 AND balance <= 1000000000000),\n  currency text NOT NULL DEFAULT 'RWF',\n  notes text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS personal_wallets_scope_idx ON personal_wallets(tenant_id, user_id);\n\nCREATE TABLE IF NOT EXISTS personal_loans (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  user_id text NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,\n  counterparty_name text NOT NULL,\n  counterparty_phone text NOT NULL DEFAULT '',\n  direction text NOT NULL CHECK (direction IN ('i_owe','they_owe')),\n  amount bigint NOT NULL CHECK (amount > 0 AND amount <= 1000000000000),\n  paid_amount bigint NOT NULL DEFAULT 0 CHECK (paid_amount >= 0 AND paid_amount <= amount),\n  due_date date,\n  notes text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','partially_paid','settled','defaulted')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS personal_loans_scope_idx ON personal_loans(tenant_id, user_id, direction, status);\n\nCREATE TABLE IF NOT EXISTS personal_investment_plans (\n  id text PRIMARY KEY,\n  tenant_id text NOT NULL REFERENCES demo_tenants(id) ON DELETE CASCADE,\n  user_id text NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  category text NOT NULL DEFAULT 'business' CHECK (category IN ('agriculture','retail','transport','real_estate','technology','services','other')),\n  capital_required bigint NOT NULL DEFAULT 0 CHECK (capital_required >= 0 AND capital_required <= 1000000000000),\n  projected_revenue bigint NOT NULL DEFAULT 0 CHECK (projected_revenue >= 0 AND projected_revenue <= 1000000000000),\n  projected_expenses bigint NOT NULL DEFAULT 0 CHECK (projected_expenses >= 0 AND projected_expenses <= 1000000000000),\n  time_horizon_months integer NOT NULL DEFAULT 12 CHECK (time_horizon_months BETWEEN 1 AND 120),\n  notes text NOT NULL DEFAULT '',\n  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','planned','active','completed','abandoned')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS personal_investment_plans_scope_idx ON personal_investment_plans(tenant_id, user_id);\n"
};
